import assert from 'node:assert/strict';
import {existsSync,readFileSync,readdirSync} from 'node:fs';
import {dirname,resolve,join} from 'node:path';
import {loadPackageFromDirectory,validatePackage} from '@jvm-expert/core';
import {NodeFileSystem} from '@jvm-expert/node';
const root='skills/container-awareness';
const loaded=await loadPackageFromDirectory(new NodeFileSystem(),root,{strict:true});
const validation=validatePackage(loaded.pkg,{directoryName:'container-awareness'});
assert.deepEqual([...loaded.issues,...validation.issues],[]);
const docs=[`${root}/SKILL.md`,...readdirSync(`${root}/references`).filter(x=>x.endsWith('.md')).map(x=>join(root,'references',x))];
let links=0;
for(const file of docs){for(const m of readFileSync(file,'utf8').matchAll(/\[[^\]]+\]\(([^)]+)\)|`((?:references\/)?[a-z0-9-]+\.md)`/g)){const target=(m[1]??m[2]).split('#')[0];if(!target||/^[a-z]+:\/\//i.test(target))continue;assert.ok(existsSync(resolve(dirname(file),target)),`${file}: ${target}`);links++;}}
assert.equal(1100*1000*1000-1024**3,26258176);
console.log(JSON.stringify({status:'PASS',issues:0,distributedFiles:loaded.pkg.files.length,markdownFiles:docs.length,localReferences:links,unitExampleBytes:26258176}));
